(function(){async function n(n,t){const i=t.textContent;t.disabled=!0;t.innerHTML='<span class="spinner-border spinner-border-sm me-1"><\/span>Добавление...';try{const r=await fetch("/Catalog/AddToCart",{method:"POST",headers:{"Content-Type":"application/x-www-form-urlencoded"},body:"id="+encodeURIComponent(n)});if(!r.ok)throw new Error("HTTP "+r.status);const u=await r.json();if(u.success){const n=document.getElementById("cartBadge");n&&(n.textContent=u.cartCount);t.innerHTML="Добавлено ✓";t.classList.remove("btn-primary");t.classList.add("btn-success");setTimeout(function(){t.textContent=i;t.classList.remove("btn-success");t.classList.add("btn-primary");t.disabled=!1},2e3)}else alert("Ошибка: "+u.message),t.textContent=i,t.disabled=!1}catch(r){console.error(r);t.textContent="Ошибка";t.disabled=!1;setTimeout(function(){t.textContent=i},2e3)}}document.addEventListener("click",async function(t){const i=t.target.closest(".add-to-cart");if(i){const r=i.dataset.productId;await n(r,i)}})})();